import { useEffect, useState, type FormEvent } from "react";
import type { Context } from "cordis";
import { Check, Plus, Tag as TagIcon, Trash2 } from "lucide-react";
import * as clientSdk from "@host/client-sdk";
import type {
  TagColor,
  TagItem,
  TagItemSlotProps,
  TagListSlotProps,
  TagWithUsage,
} from "./contract.d.ts";

export const probeClientSdkExports: keyof typeof clientSdk =
  "___PROBE_CLIENT_SDK_EXPORTS___";
export const probeContextKeys: keyof Context = "___PROBE_CONTEXT_KEYS___";
export const probeRouterKeys: keyof Context["router"] =
  "___PROBE_ROUTER_KEYS___";
export const probeSlotKeys: keyof Context["slot"] = "___PROBE_SLOT_KEYS___";
export const probeSlotsKeys: keyof Context["slots"] = "___PROBE_SLOTS_KEYS___";
export const probeUiKeys: keyof Context["ui"] = "___PROBE_UI_KEYS___";
export const probeSlotRegisterParams: Parameters<Context["slot"]["register"]> = 0;
export const probeSlotsRegisterParams: Parameters<Context["slots"]["register"]> =
  0;

const COLOR_ORDER: readonly TagColor[] = [
  "accent",
  "amber",
  "emerald",
  "rose",
  "violet",
  "slate",
];

const COLOR_SWATCHES: Record<TagColor, string> = {
  accent: "#6366f1",
  amber: "#f59e0b",
  emerald: "#10b981",
  rose: "#f43f5e",
  violet: "#8b5cf6",
  slate: "#64748b",
};

function swatch(color: TagColor): string {
  return COLOR_SWATCHES[color] ?? COLOR_SWATCHES.accent;
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

async function requestJson<T>(url: string, init?: RequestInit): Promise<T> {
  const response = await fetch(url, {
    ...init,
    headers: {
      "content-type": "application/json",
      ...(init?.headers ?? {}),
    },
  });
  const text = await response.text();
  const data = text ? (JSON.parse(text) as Record<string, unknown>) : {};
  if (!response.ok) {
    const message =
      typeof data.error === "string" && data.error.length > 0
        ? data.error
        : `请求失败 (${response.status})`;
    throw new Error(message);
  }
  return data as T;
}

async function fetchTagCatalog(): Promise<TagWithUsage[]> {
  const data = await requestJson<{ tags: TagWithUsage[] }>(
    "/api/app/todo-tags/tags",
  );
  return data.tags ?? [];
}

async function fetchTaskTags(taskId: string): Promise<TagItem[]> {
  const data = await requestJson<{ tags: TagItem[] }>(
    `/api/app/todo-tags/tasks/${encodeURIComponent(taskId)}/tags`,
  );
  return data.tags ?? [];
}

const tagListeners = new Set<() => void>();
let tagRevision = 0;

function notifyTagsChanged(): void {
  tagRevision += 1;
  for (const listener of tagListeners) listener();
}

function useTagRevision(): number {
  const [revision, setRevision] = useState(tagRevision);
  useEffect(() => {
    const listener = () => setRevision(tagRevision);
    tagListeners.add(listener);
    return () => {
      tagListeners.delete(listener);
    };
  }, []);
  return revision;
}

export function TaskTagBadges({ task }: TagItemSlotProps) {
  const revision = useTagRevision();
  const [tags, setTags] = useState<TagItem[]>([]);
  const [failed, setFailed] = useState(false);

  useEffect(() => {
    let cancelled = false;
    fetchTaskTags(task.id)
      .then((next) => {
        if (cancelled) return;
        setTags(next);
        setFailed(false);
      })
      .catch(() => {
        if (!cancelled) setFailed(true);
      });
    return () => {
      cancelled = true;
    };
  }, [task.id, revision]);

  if (failed || tags.length === 0) return null;
  const visible = tags.slice(0, 3);
  const hidden = tags.length - visible.length;

  return (
    <span
      data-todo-tag-badges={task.id}
      className="inline-flex flex-wrap items-center gap-1"
    >
      {visible.map((tag) => (
        <span
          key={tag.id}
          data-todo-tag-badge={tag.name}
          title={tag.name}
          className="inline-flex max-w-28 items-center gap-1 rounded-full border border-line bg-canvas px-1.5 py-0.5 text-[11px] leading-none text-ink"
        >
          <span
            className="size-1.5 shrink-0 rounded-full"
            style={{ backgroundColor: swatch(tag.color) }}
            aria-hidden="true"
          />
          <span className="truncate">{tag.name}</span>
        </span>
      ))}
      {hidden > 0 && (
        <span className="rounded-full border border-line bg-canvas px-1.5 py-0.5 text-[11px] leading-none text-muted">
          +{hidden}
        </span>
      )}
    </span>
  );
}

export function TaskTagEditor({ task }: TagItemSlotProps) {
  const revision = useTagRevision();
  const [catalog, setCatalog] = useState<TagWithUsage[]>([]);
  const [selected, setSelected] = useState<readonly string[]>([]);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [draft, setDraft] = useState("");
  const [draftColor, setDraftColor] = useState<TagColor>("accent");

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    Promise.all([fetchTagCatalog(), fetchTaskTags(task.id)])
      .then(([nextCatalog, mine]) => {
        if (cancelled) return;
        setCatalog(nextCatalog);
        setSelected(mine.map((tag) => tag.id));
        setError("");
      })
      .catch((err) => {
        if (!cancelled) setError(errorMessage(err));
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [task.id, revision]);

  const persist = async (tagIds: readonly string[]) => {
    if (busy) return;
    setBusy(true);
    setError("");
    try {
      const data = await requestJson<{ tags: TagItem[] }>(
        `/api/app/todo-tags/tasks/${encodeURIComponent(task.id)}/tags`,
        { method: "PATCH", body: JSON.stringify({ tagIds }) },
      );
      setSelected((data.tags ?? []).map((tag) => tag.id));
      notifyTagsChanged();
    } catch (err) {
      setError(errorMessage(err));
    } finally {
      setBusy(false);
    }
  };

  const toggle = (tagId: string) => {
    const next = selected.includes(tagId)
      ? selected.filter((id) => id !== tagId)
      : [...selected, tagId];
    setSelected(next);
    void persist(next);
  };

  const handleCreate = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const name = draft.trim();
    if (!name || busy) return;
    setBusy(true);
    setError("");
    try {
      const data = await requestJson<{ tag: TagItem }>(
        "/api/app/todo-tags/tags",
        { method: "POST", body: JSON.stringify({ name, color: draftColor }) },
      );
      setDraft("");
      const next = [...selected, data.tag.id];
      setSelected(next);
      notifyTagsChanged();
      const attached = await requestJson<{ tags: TagItem[] }>(
        `/api/app/todo-tags/tasks/${encodeURIComponent(task.id)}/tags`,
        { method: "PATCH", body: JSON.stringify({ tagIds: next }) },
      );
      setSelected((attached.tags ?? []).map((tag) => tag.id));
      notifyTagsChanged();
    } catch (err) {
      setError(errorMessage(err));
    } finally {
      setBusy(false);
    }
  };

  return (
    <section data-todo-tag-editor={task.id} className="space-y-2">
      <header className="flex items-center justify-between">
        <h3 className="text-xs font-medium text-muted">标签</h3>
        <span className="text-[11px] text-muted">
          {selected.length > 0 ? `已选 ${selected.length}` : "未添加"}
        </span>
      </header>

      {loading ? (
        <p className="text-xs text-muted">正在加载标签…</p>
      ) : catalog.length === 0 ? (
        <p className="text-xs text-muted">还没有标签，在下方创建第一个标签。</p>
      ) : (
        <div className="flex flex-wrap gap-1.5">
          {catalog.map((tag) => {
            const active = selected.includes(tag.id);
            return (
              <button
                key={tag.id}
                type="button"
                disabled={busy}
                aria-pressed={active}
                data-todo-tag-toggle={tag.name}
                onClick={() => toggle(tag.id)}
                className={`inline-flex min-h-8 items-center gap-1.5 rounded-full border px-2.5 text-xs transition-colors ${
                  active
                    ? "border-accent/40 bg-accent-soft font-medium text-accent"
                    : "border-line bg-surface text-ink hover:bg-canvas"
                }`}
              >
                <span
                  className="size-1.5 rounded-full"
                  style={{ backgroundColor: swatch(tag.color) }}
                  aria-hidden="true"
                />
                <span className="truncate">{tag.name}</span>
                {active && <Check className="size-3" aria-hidden="true" />}
              </button>
            );
          })}
        </div>
      )}

      <form onSubmit={(e) => void handleCreate(e)} className="space-y-1.5">
        <div className="flex items-center gap-1.5">
          <input
            type="text"
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            placeholder="新建标签名称"
            aria-label="新建标签名称"
            data-todo-tag-input="true"
            className="min-h-9 min-w-0 flex-1 rounded-md border border-line bg-surface px-2.5 text-sm text-ink outline-none focus:border-accent focus:ring-1 focus:ring-accent"
          />
          <button
            type="submit"
            disabled={busy || !draft.trim()}
            className="inline-flex min-h-9 shrink-0 items-center gap-1 rounded-md bg-accent px-2.5 text-xs font-medium text-surface transition-colors hover:bg-accent/90 disabled:opacity-45"
          >
            <Plus className="size-3.5" aria-hidden="true" />
            添加
          </button>
        </div>
        <div
          className="flex flex-wrap items-center gap-1"
          role="group"
          aria-label="标签颜色"
        >
          {COLOR_ORDER.map((color) => (
            <button
              key={color}
              type="button"
              aria-label={`颜色 ${color}`}
              aria-pressed={draftColor === color}
              onClick={() => setDraftColor(color)}
              data-todo-tag-color={color}
              className={`flex size-6 items-center justify-center rounded-full border ${
                draftColor === color ? "border-ink" : "border-transparent"
              }`}
            >
              <span
                className="size-3 rounded-full"
                style={{ backgroundColor: swatch(color) }}
                aria-hidden="true"
              />
            </button>
          ))}
        </div>
      </form>

      {error && (
        <p role="alert" className="text-xs text-danger">
          {error}
        </p>
      )}
    </section>
  );
}

export function TagSidebarSection({ tasks, refresh }: TagListSlotProps) {
  const revision = useTagRevision();
  const [catalog, setCatalog] = useState<TagWithUsage[]>([]);
  const [name, setName] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    let cancelled = false;
    fetchTagCatalog()
      .then((next) => {
        if (!cancelled) {
          setCatalog(next);
          setError("");
        }
      })
      .catch((err) => {
        if (!cancelled) setError(errorMessage(err));
      });
    return () => {
      cancelled = true;
    };
  }, [revision]);

  const handleCreate = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const trimmed = name.trim();
    if (!trimmed || busy) return;
    setBusy(true);
    setError("");
    try {
      await requestJson<{ tag: TagItem }>("/api/app/todo-tags/tags", {
        method: "POST",
        body: JSON.stringify({ name: trimmed }),
      });
      setName("");
      notifyTagsChanged();
      await refresh();
    } catch (err) {
      setError(errorMessage(err));
    } finally {
      setBusy(false);
    }
  };

  const handleDelete = async (tag: TagWithUsage) => {
    if (busy) return;
    setBusy(true);
    setError("");
    try {
      await requestJson(`/api/app/todo-tags/tags/${encodeURIComponent(tag.id)}`, {
        method: "DELETE",
      });
      notifyTagsChanged();
      await refresh();
    } catch (err) {
      setError(errorMessage(err));
    } finally {
      setBusy(false);
    }
  };

  return (
    <section
      data-todo-tag-catalog="true"
      className="space-y-2 rounded-md border border-line bg-surface/70 p-2.5"
    >
      <header className="flex items-center justify-between gap-2">
        <span className="flex items-center gap-1.5 text-xs font-medium text-ink">
          <TagIcon className="size-3.5 text-muted" aria-hidden="true" />
          标签
        </span>
        <span className="text-[11px] text-muted">{tasks.length} 个任务</span>
      </header>

      {catalog.length === 0 ? (
        <p className="text-[11px] text-muted">还没有标签。</p>
      ) : (
        <ul className="space-y-1">
