testFiles.todo-tags.spec.ts:
import assert from "node:assert/strict";
import type { PluginTestContext } from "@host/server-sdk";

interface TagShape {
  readonly id: string;
  readonly name: string;
  readonly color: string;
  readonly taskCount: number;
}

export default async function (ctx: PluginTestContext): Promise<void> {
  const taskResponse = await ctx.request({
    method: "POST",
    path: "/api/app/todo-core/tasks",
    body: { title: "Tagged Task" },
  });
  assert.equal(taskResponse.status, 201);
  const taskId = (taskResponse.body as { task: { id: string } }).task.id;

  const createResponse = await ctx.request({
    method: "POST",
    path: "/api/app/todo-tags/tags",
    body: { name: "  Urgent  ", color: "rose" },
  });
  assert.equal(createResponse.status, 201);
  const tag = (createResponse.body as { tag: TagShape }).tag;
  assert.equal(tag.name, "Urgent");
  assert.equal(tag.color, "rose");

  const duplicateResponse = await ctx.request({
    method: "POST",
    path: "/api/app/todo-tags/tags",
    body: { name: "urgent" },
  });
  assert.equal(duplicateResponse.status, 409);

  const attachResponse = await ctx.request({
    method: "PATCH",
    path: `/api/app/todo-tags/tasks/${taskId}/tags`,
    body: { tagIds: [tag.id] },
  });
  assert.equal(attachResponse.status, 200);
  assert.equal((attachResponse.body as { tags: TagShape[] }).tags.length, 1);

  const taskTagsResponse = await ctx.request({
    method: "GET",
    path: `/api/app/todo-tags/tasks/${taskId}/tags`,
  });
  assert.equal(taskTagsResponse.status, 200);
  assert.equal(
    (taskTagsResponse.body as { tags: TagShape[] }).tags[0]?.name,
    "Urgent",
  );

  const catalogResponse = await ctx.request({
    method: "GET",
    path: "/api/app/todo-tags/tags",
  });
  assert.equal(catalogResponse.status, 200);
  assert.equal(
    (catalogResponse.body as { tags: TagShape[] }).tags[0]?.taskCount,
    1,
  );

  const detachResponse = await ctx.request({
    method: "DELETE",
    path: `/api/app/todo-tags/tasks/${taskId}/tags/${tag.id}`,
  });
  assert.equal(detachResponse.status, 200);
  assert.equal((detachResponse.body as { tags: TagShape[] }).tags.length, 0);

  const deleteResponse = await ctx.request({
    method: "DELETE",
    path: `/api/app/todo-tags/tags/${tag.id}`,
  });
  assert.equal(deleteResponse.status, 200);

  const finalCatalog = await ctx.request({
    method: "GET",
    path: "/api/app/todo-tags/tags",
  });
  assert.equal((finalCatalog.body as { tags: TagShape[] }).tags.length, 0);
}

