Public methods:

```ts
list(): TagWithUsage[] {
  const rows = this.db.prepare("SELECT id, name, color, created_at FROM plg_todo_tags__tags ORDER BY name COLLATE NOCASE ASC").all<TagRow>();
  const known = this.existingTaskIds();
  const counts = new Map<string, number>();
  for (const link of this.db.prepare("SELECT task_id, tag_id FROM plg_todo_tags__task_tags").all<LinkRow>()) {
    if (!known.has(link.task_id)) continue;
    counts.set(link.tag_id, (counts.get(link.tag_id) ?? 0) + 1);
  }
  return rows.map(row => ({ ...toTagItem(row), taskCount: counts.get(row.id) ?? 0 }));
}

get(id: string): TagItem | null {...}

create(input: string | CreateTagInput): TagItem {
  const rawName = typeof input === "string" ? input : input.name;
  const name = normalizeTagName(rawName);
  const color = typeof input === "string" ? DEFAULT_COLOR : resolveColor(input.color);
  const now = new Date().toISOString();
  const id = globalThis.crypto.randomUUID();
  try {
    this.db.prepare("INSERT INTO plg_todo_tags__tags (id, name, color, created_at) VALUES (?, ?, ?, ?)").run(id, name, color, now);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    if (message.toLowerCase().includes("unique")) throw httpError(409, `Tag "${name}" already exists`);
    throw error;
  }
  return this.get(id)!;
}

delete(id: string): boolean {
  const existing = this.get(id);
  if (!existing) return false;
  this.db.prepare("DELETE FROM plg_todo_tags__task_tags WHERE tag_id = ?").run(id);
  const result = this.db.prepare("DELETE FROM plg_todo_tags__tags WHERE id = ?").run(id);
  return Number(result.changes) > 0;
}

listForTask(taskId: string): TagItem[] {
  return this.tagsForTask(taskId);
}

setForTask(taskId: string, tagIds: readonly string[]): TagItem[] {
  this.ensureTask(taskId);
  if (!Array.isArray(tagIds)) throw httpError(400, "tagIds must be an array of tag ids");
  const unique: string[] = [];
  for (const value of tagIds) {
    if (typeof value !== "string" || value.length === 0) throw httpError(400, "tagIds must be an array of tag ids");
    if (!unique.includes(value)) unique.push(value);
  }
  const missing = unique.filter(id => !this.get(id));
  if (missing.length > 0) throw httpError(400, `Unknown tag ids: ${missing.join(", ")}`);
  const now = new Date().toISOString();
  this.db.prepare("DELETE FROM plg_todo_tags__task_tags WHERE task_id = ?").run(taskId);
  for (const tagId of unique) {
    this.db.prepare("INSERT INTO plg_todo_tags__task_tags (task_id, tag_id, created_at) VALUES (?, ?, ?)").run(taskId, tagId, now);
  }
  const tags = this.tagsForTask(taskId);
  this.ctx.emit("tags:changed", { taskId, tags });
  return tags;
}

addToTask(taskId, tagId): TagItem[] {
  this.ensureTask(taskId);
  if (!this.get(tagId)) throw httpError(404, "Tag not found");
  const now = new Date().toISOString();
  const existingLink = this.db.prepare("SELECT task_id FROM plg_todo_tags__task_tags WHERE task_id = ? AND tag_id = ?").get(taskId, tagId);
  if (!existingLink) this.db.prepare("INSERT ...").run(taskId, tagId, now);
  const tags = this.tagsForTask(taskId);
  this.ctx.emit("tags:changed", { taskId, tags });
  return tags;
}

removeFromTask(taskId, tagId): TagItem[] {
  this.ensureTask(taskId);
  this.db.prepare("DELETE FROM plg_todo_tags__task_tags WHERE task_id = ? AND tag_id = ?").run(taskId, tagId);
  const tags = this.tagsForTask(taskId);
  this.ctx.emit("tags:changed", { taskId, tags });
  return tags;
}
