  "___PROBE_SERVER_SDK_EXPORTS___";
export const probeScopedDbKeys: keyof serverSdk.ScopedDb = "___PROBE_SCOPED_DB_KEYS___";

const TAG_COLORS: readonly TagColor[] = [
  "accent",
  "amber",
  "emerald",
  "rose",
  "violet",
  "slate",
];

const DEFAULT_COLOR: TagColor = "accent";
const MAX_NAME_LENGTH = 40;

interface TagRow {
  readonly id: string;
  readonly name: string;
  readonly color: string;
  readonly created_at: string;
}

interface LinkRow {
  readonly task_id: string;
  readonly tag_id: string;
}

interface TaskRef {
  readonly id: string;
}

interface TodoLike {
  get(id: string): TaskRef | null;
  list(filter?: { readonly state?: "open" | "done" }): readonly TaskRef[];
}

function httpError(status: number, message: string): Error & { status: number } {
  const error = new Error(message) as Error & { status: number };
  error.status = status;
  return error;
}

function toErrorResponse(error: unknown): {
  status: number;
  body: { error: string };
} {
  const candidate = error as { status?: unknown } | null;
  const status =
    candidate && typeof candidate.status === "number" ? candidate.status : 500;
  const message = error instanceof Error ? error.message : String(error);
  return { status, body: { error: message } };
}

function isTagColor(value: unknown): value is TagColor {
  return (
    typeof value === "string" &&
    (TAG_COLORS as readonly string[]).includes(value)
  );
}

function normalizeName(raw: unknown): string {
  if (typeof raw !== "string") {
    throw httpError(400, "Tag name is required");
  }
  const name = raw.trim();
  if (!name) {
    throw httpError(400, "Tag name is required");
  }
  if (name.length > MAX_NAME_LENGTH) {
    throw httpError(400, `Tag name must be ${MAX_NAME_LENGTH} characters or fewer`);
  }
  return name;
}

function resolveColor(raw: unknown): TagColor {
  if (raw === undefined || raw === null) return DEFAULT_COLOR;
  if (!isTagColor(raw)) {
    throw httpError(400, `Unsupported tag color: ${String(raw)}`);
  }
  return raw;
}

function toTagItem(row: TagRow): TagItem {
  return {
    id: row.id,
    name: row.name,
    color: isTagColor(row.color) ? row.color : DEFAULT_COLOR,
    createdAt: row.created_at,
  };
}

