function normalizeName(raw: unknown): string {
  if (typeof raw !== "string") {
    throw httpError(400, "Tag name is required");
  }
  const name = raw.trim();
  if (!name) {
    throw httpError(400, "Tag name is required");
  }
  if (name.length > MAX_NAME_LENGTH) {
    throw httpError(
      400,
      `Tag name must be ${MAX_NAME_LENGTH} characters or fewer`,
    );
  }
  return name;
}

function resolveColor(raw: unknown): TagColor {
  if (raw === undefined || raw === null) return DEFAULT_COLOR;
  if (!isTagColor(raw)) {
    throw httpError(400, `Unsupported tag color: ${String(raw)}`);
  }
  return raw;
}

function toTagItem(row: TagRow): TagItem {
  return {
    id: row.id,
    name: row.name,
    color: isTagColor(row.color) ? row.color : DEFAULT_COLOR,
    createdAt: row.created_at,
  };
}

export default class TodoTagsService extends Service implements TagService {
  private readonly db: serverSdk.ScopedDb;

  constructor(ctx: Context) {
    super(ctx, "tags");
    this.db = ctx.db;

    this.db.exec(
      "CREATE TABLE IF NOT EXISTS plg_todo_tags__tags (" +
        "id TEXT PRIMARY KEY, " +
        "name TEXT NOT NULL COLLATE NOCASE UNIQUE, " +
        "color TEXT NOT NULL DEFAULT 'accent', " +
        "created_at TEXT NOT NULL" +
        ")",
    );
    this.db.exec(
      "CREATE TABLE IF NOT EXISTS plg_todo_tags__task_tags (" +
        "task_id TEXT NOT NULL, " +
        "tag_id TEXT NOT NULL, " +
        "created_at TEXT NOT NULL, " +
        "PRIMARY KEY (task_id, tag_id)" +
        ")",
    );
    this.db.exec(
      "CREATE INDEX IF NOT EXISTS plg_todo_tags__task_tags_tag ON plg_todo_tags__task_tags (tag_id)",
    );

    ctx.http.route("GET", "/tags", () => ({ tags: this.list() }));

    ctx.http.route("GET", "/tags/:id", (req) => {
      const tag = this.get(req.params.id);
      if (!tag) {
        return { status: 404, body: { error: "Tag not found" } };
      }
      return { tag };
    });

    ctx.http.route("POST", "/tags", (req) => {
      try {
        const body = (req.body ?? {}) as { name?: unknown; color?: unknown };
        const tag = this.create({
          name: normalizeName(body.name),
          color: resolveColor(body.color),
        });
        return { status: 201, body: { tag } };
      } catch (error) {
        return toErrorResponse(error);
      }
    });

    ctx.http.route("DELETE", "/tags/:id", (req) => {
      if (!this.delete(req.params.id)) {
        return { status: 404, body: { error: "Tag not found" } };
      }
      return { deleted: true, id: req.params.id };
    });

    ctx.http.route("GET", "/tasks/:taskId/tags", (req) => {
      try {
        this.ensureTask(req.params.taskId);
        return { tags: this.tagsForTask(req.params.taskId) };
      } catch (error) {
        return toErrorResponse(error);
      }
    });

    ctx.http.route("PATCH", "/tasks/:taskId/tags", (req) => {
      try {
        const body = (req.body ?? {}) as { tagIds?: unknown };
        if (!Array.isArray(body.tagIds)) {
          return {
            status: 400,
            body: { error: "tagIds must be an array of tag ids" },
          };
        }
        const tagIds: string[] = [];
        for (const value of body.tagIds) {
          if (typeof value !== "string" || value.length === 0) {
            return {
              status: 400,
              body: { error: "tagIds must be an array of tag ids" },
            };
          }
          tagIds.push(value);
        }
        return { tags: this.setForTask(req.params.taskId, tagIds) };
      } catch (error) {
        return toErrorResponse(error);
      }
    });

    ctx.http.route("POST", "/tasks/:taskId/tags", (req) => {
      try {
        const body = (req.body ?? {}) as { tagId?: unknown };
        if (typeof body.tagId !== "string" || body.tagId.length === 0) {
          return { status: 400, body: { error: "tagId is required" } };
        }
        return { tags: this.addToTask(req.params.taskId, body.tagId) };
      } catch (error) {
        return toErrorResponse(error);
      }
    });

    ctx.http.route("DELETE", "/tasks/:taskId/tags/:tagId", (req) => {
      try {
        return {
          tags: this.removeFromTask(req.params.taskId, req.params.tagId),
        };
      } catch (error) {
        return toErrorResponse(error);
      }
    });
  }

  list(): TagWithUsage[] {
    const rows = this.db
      .prepare(
        "SELECT id, name, color, created_at FROM plg_todo_tags__tags ORDER BY name COLLATE NOCASE ASC",
      )
      .all<TagRow>();
    const known = this.existingTaskIds();
    const counts = new Map<string, number>();
    const links = this.db
      .prepare("SELECT task_id, tag_id FROM plg_todo_tags__task_tags")
      .all<LinkRow>();
    for (const link of links) {
      if (!known.has(link.task_id)) continue;
      counts.set(link.tag_id, (counts.get(link.tag_id) ?? 0) + 1);
    }
    return rows.map((row) => ({
      ...toTagItem(row),
      taskCount: counts.get(row.id) ?? 0,
    }));
  }

  get(id: string): TagItem | null {
    const row = this.db
      .prepare(
        "SELECT id, name, color, created_at FROM plg_todo_tags__tags WHERE id = ?",
      )
      .get<TagRow>(id);
    return row ? toTagItem(row) : null;
  }

  create(input: string | CreateTagInput): TagItem {
    const rawName = typeof input === "string" ? input : input.name;
    const name = normalizeName(rawName);
    const color =
      typeof input === "string" ? DEFAULT_COLOR : resolveColor(input.color);
    const now = new Date().toISOString();
    const id = globalThis.crypto.randomUUID();
    try {
      this.db
        .prepare(
          "INSERT INTO plg_todo_tags__tags (id, name, color, created_at) VALUES (?, ?, ?, ?)",
        )
        .run(id, name, color, now);
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      if (message.toLowerCase().includes("unique")) {
        throw httpError(409, `Tag "${name}" already exists`);
      }
      throw error;
    }
    const created = this.get(id);
    if (!created) {
      throw httpError(500, "Failed to create tag");
    }
    return created;
  }

  delete(id: string): boolean {
    if (!this.get(id)) return false;
    this.db
      .prepare("DELETE FROM plg_todo_tags__task_tags WHERE tag_id = ?")
      .run(id);
    const result = this.db
      .prepare("DELETE FROM plg_todo_tags__tags WHERE id = ?")
      .run(id);
    return Number(result.changes) > 0;
  }

  listForTask(taskId: string): TagItem[] {
    return this.tagsForTask(taskId);
  }

  setForTask(taskId: string, tagIds: readonly string[]): TagItem[] {
    this.ensureTask(taskId);
    const unique: string[] = [];
    for (const value of tagIds) {
      if (typeof value !== "string" || value.length === 0) {
        throw httpError(400, "tagIds must be an array of tag ids");
      }
      if (!unique.includes(value)) unique.push(value);
    }
    const missing = unique.filter((id) => this.get(id) === null);
    if (missing.length > 0) {
      throw httpError(400, `Unknown tag ids: ${missing.join(", ")}`);
    }
    const now = new Date().toISOString();
    this.db
      .prepare("DELETE FROM plg_todo_tags__task_tags WHERE task_id = ?")
      .run(taskId);
    for (const tagId of unique) {
      this.db
        .prepare(
          "INSERT INTO plg_todo_tags__task_tags (task_id, tag_id, created_at) VALUES (?, ?, ?)",
        )
        .run(taskId, tagId, now);
    }
    return this.emitTaskTags(taskId);
  }

  addToTask(taskId: string, tagId: string): TagItem[] {
    this.ensureTask(taskId);
    if (!this.get(tagId)) {
      throw httpError(404, "Tag not found");
    }
    const existing = this.db
      .prepare(
        "SELECT task_id FROM plg_todo_tags__task_tags WHERE task_id = ? AND tag_id = ?",
      )
      .get<{ task_id: string }>(taskId, tagId);
    if (!existing) {
      this.db
        .prepare(
          "INSERT INTO plg_todo_tags__task_tags (task_id, tag_id, created_at) VALUES (?, ?, ?)",
        )
        .run(taskId, tagId, new Date().toISOString());
    }
    return this.emitTaskTags(taskId);
  }

  removeFromTask(taskId: string, tagId: string): TagItem[] {
    this.ensureTask(taskId);
    this.db
      .prepare(
        "DELETE FROM plg_todo_tags__task_tags WHERE task_id = ? AND tag_id = ?",
      )
      .run(taskId, tagId);
    return this.emitTaskTags(taskId);
  }

  private todo(): TodoLike {
    const todo = (this.ctx as unknown as { todo?: TodoLike }).todo;
    if (!todo) {
      throw httpError(503, "todo-core service is unavailable");
    }
    return todo;
  }

  private ensureTask(taskId: string): TaskRef {
    const task = this.todo().get(taskId);
    if (!task) {
      throw httpError(404, "Task not found");
    }
    return task;
  }

  private existingTaskIds(): Set<string> {
    const ids = new Set<string>();
    try {
      for (const task of this.todo().list()) {
        ids.add(task.id);
      }
    } catch {
      // todo-core unavailable: keep counts resilient
    }
    return ids;
  }

  private tagsForTask(taskId: string): TagItem[] {
    const rows = this.db
      .prepare(
        "SELECT t.id AS id, t.name AS name, t.color AS color, t.created_at AS created_at " +
          "FROM plg_todo_tags__task_tags AS l " +
          "JOIN plg_todo_tags__tags AS t ON t.id = l.tag_id " +
          "WHERE l.task_id = ? " +
          "ORDER BY t.name COLLATE NOCASE ASC",
      )
      .all<TagRow>(taskId);
    return rows.map(toTagItem);
  }

  private emitTaskTags(taskId: string): TagItem[] {
    const tags = this.tagsForTask(taskId);
    this.ctx.emit("tags:changed", { taskId, tags });
    return tags;
  }
}
", "client.tsx": "import { useEffect, useState, type FormEvent } from "react";
import type { Context } from "cordis";
import { Check, Plus, Tag as TagIcon, Trash2 } from "lucide-react";
import * as clientSdk from "@host/client-sdk";
import type {
  TagColor,
  TagItem,
  TagItemSlotProps,
  TagListSlotProps,
  TagWithUsage,
} from "./contract.d.ts";

export const probeClientSdkExports: keyof typeof clientSdk =
  "___PROBE_CLIENT_SDK_EXPORTS___";
export const probeContextKeys: keyof Context = "___PROBE_CONTEXT_KEYS___";
export const probeRouterKeys: keyof Context["router"] =
  "___PROBE_ROUTER_KEYS___";
export const probeSlotKeys: keyof Context["slot"] = "___PROBE_SLOT_KEYS___";
export const probeSlotsKeys: keyof Context["slots"] = "___PROBE_SLOTS_KEYS___";
export const probeUiKeys: keyof Context["ui"] = "___PROBE_UI_KEYS___";
export const probeSlotRegisterParams: Parameters<Context["slot"]["register"]> = 0;
export const probeSlotsRegisterParams: Parameters<Context["slots"]["register"]> =
  0;

const COLOR_ORDER: readonly TagColor[] = [
  "accent",
  "amber",
  "emerald",
  "rose",
  "violet",
  "slate",
];

const COLOR_SWATCHES: Record<TagColor, string> = {
  accent: "#6366f1",
  amber: "#f59e0b",
  emerald: "#10b981",
  rose: "#f43f5e",
  violet: "#8b5cf6",
  slate: "#64748b",
};

function swatch(color: TagColor): string {
  return COLOR_SWATCHES[color] ?? COLOR_SWATCHES.accent;
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

async function requestJson<T>(url: string, init?: RequestInit): Promise<T> {
  const response = await fetch(url, {
    ...init,
    headers: {
      "content-type": "application/json",
      ...(init?.headers ?? {}),
    },
  });
  const text = await response.text();
  const data = text ? (JSON.parse(text) as Record<string, unknown>) : {};
  if (!response.ok) {
    const message =
      typeof data.error === "string" && data.error.length > 0
        ? data.error
        : `请求失败 (${response.status})`;
    throw new Error(message);
  }
  return data as T;
}

async function fetchTagCatalog(): Promise<TagWithUsage[]> {
  const data = await requestJson<{ tags: TagWithUsage[] }>(
    "/api/app/todo-tags/tags",
  );
  return data.tags ?? [];
}

async function fetchTaskTags(taskId: string): Promise<TagItem[]> {
  const data = await requestJson<{ tags: TagItem[] }>(
    `/api/app/todo-tags/tasks/${encodeURIComponent(taskId)}/tags`,
  );
  return data.tags ?? [];
}

const tagListeners = new Set<() => void>();
let tagRevision = 0;

function notifyTagsChanged(): void {
  tagRevision += 1;
  for (const listener of tagListeners) listener();
}

function useTagRevision(): number {
  const [revision, setRevision] = useState(tagRevision);
  useEffect(() => {
    const listener = () => setRevision(tagRevision);
    tagListeners.add(listener);
    return () => {
      tagListeners.delete(listener);
    };
  }, []);
  return revision;
}

export function TaskTagBadges({ task }: TagItemSlotProps) {
  const revision = useTagRevision();
  const [tags, setTags] = useState<TagItem[]>([]);
  const [failed, setFailed] = useState(false);

  useEffect(() => {
    let cancelled = false;
    fetchTaskTags(task.id)
      .then((next) => {
        if (cancelled) return;
        setTags(next);
        setFailed(false);
      })
      .catch(() => {
        if (!cancelled) setFailed(true);
      });
    return () => {
      cancelled = true;
    };
  }, [task.id, revision]);

  if (failed || tags.length === 0) return null;
  const visible = tags.slice(0, 3);
  const hidden = tags.length - visible.length;

  return (
    <span
      data-todo-tag-badges={task.id}
      className="inline-flex flex-wrap items-center gap-1"
    >
      {visible.map((tag) => (
        <span
          key={tag.id}
          data-todo-tag-badge={tag.name}
          title={tag.name}
          className="inline-flex max-w-28 items-center gap-1 rounded-full border border-line bg-canvas px-1.5 py-0.5 text-[11px] leading-none text-ink"
        >
          <span
            className="size-1.5 shrink-0 rounded-full"
            style={{ backgroundColor: swatch(tag.color) }}
            aria-hidden="true"
          />
          <span className="truncate">{tag.name}</span>
        </span>
      ))}
      {hidden > 0 && (
        <span className="rounded-full border border-line bg-canvas px-1.5 py-0.5 text-[11px] leading-none text-muted">
          +{hidden}
        </span>
      )}
    </span>
  );
}

export function TaskTagEditor({ task }: TagItemSlotProps) {
  const revision = useTagRevision();
  const [catalog, setCatalog] = useState<TagWithUsage[]>([]);
  const [selected, setSelected] = useState<readonly string[]>([]);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [draft, setDraft] = useState("");
  const [draftColor, setDraftColor] = useState<TagColor>("accent");

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    Promise.all([fetchTagCatalog(), fetchTaskTags(task.id)])
      .then(([nextCatalog, mine]) => {
        if (cancelled) return;
        setCatalog(nextCatalog);
        setSelected(mine.map((tag) => tag.id));
        setError("");
      })
      .catch((err) => {
        if (!cancelled) setError(errorMessage(err));
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [task.id, revision]);

  const persist = async (tagIds: readonly string[]) => {
    if (busy) return;
    setBusy(true);
    setError("");
    try {
      const data = await requestJson<{ tags: TagItem[] }>(
        `/api/app/todo-tags/tasks/${encodeURIComponent(task.id)}/tags`,
        { method: "PATCH", body: JSON.stringify({ tagIds }) },
      );
      setSelected((data.tags ?? []).map((tag) => tag.id));
      notifyTagsChanged();
    } catch (err) {
      setError(errorMessage(err));
    } finally {
      setBusy(false);
    }
  };

  const toggle = (tagId: string) => {
    const next = selected.includes(tagId)
      ? selected.filter((id) => id !== tagId)
      : [...selected, tagId];
    setSelected(next);
    void persist(next);
  };

  const handleCreate = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const name = draft.trim();
    if (!name || busy) return;
    setBusy(true);
    setError("");
    try {
      const data = await requestJson<{ tag: TagItem }>(
        "/api/app/todo-tags/tags",
        { method: "POST", body: JSON.stringify({ name, color: draftColor }) },
      );
      setDraft("");
      const next = [...selected, data.tag.id];
      setSelected(next);
      notifyTagsChanged();
      const attached = await requestJson<{ tags: TagItem[] }>(
        `/api/app/todo-tags/tasks/${encodeURIComponent(task.id)}/tags`,
        { method: "PATCH", body: JSON.stringify({ tagIds: next }) },
      );
      setSelected((attached.tags ?? []).map((tag) => tag.id));
      notifyTagsChanged();
    } catch (err) {
      setError(errorMessage(err));
    } finally {
      setBusy(false);
    }
  };

  return (
    <section data-todo-tag-editor={task.id} className="space-y-2">
      <header className="flex items-center justify-between">
        <h3 className="text-xs font-medium text-muted">标签</h3>
        <span className="text-[11px] text-muted">
          {selected.length > 0 ? `已选 ${selected.length}` : "未添加"}
        </span>
      </header>

      {loading ? (
        <p className="text-xs text-muted">正在加载标签…</p>
      ) : catalog.length === 0 ? (
        <p className="text-xs text-muted">还没有标签，在下方创建第一个标签。</p>
      ) : (
        <div className="flex flex-wrap gap-1.5">
          {catalog.map((tag) => {
            const active = selected.includes(tag.id);
            return (
              <button
                key={tag.id}
                type="button"
                disabled={busy}
                aria-pressed={active}
                data-todo-tag-toggle={tag.name}
                onClick={() => toggle(tag.id)}
                className={`inline-flex min-h-8 items-center gap-1.5 rounded-full border px-2.5 text-xs transition-colors ${
                  active
                    ? "border-accent/40 bg-accent-soft font-medium text-accent"
                    : "border-line bg-surface text-ink hover:bg-canvas"
                }`}
              >
                <span
                  className="size-1.5 rounded-full"
                  style={{ backgroundColor: swatch(tag.color) }}
                  aria-hidden="true"
                />
                <span className="truncate">{tag.name}</span>
                {active && <Check className="size-3" aria-hidden="true" />}
              </button>
            );
          })}
        </div>
      )}

      <form onSubmit={(e) => void handleCreate(e)} className="space-y-1.5">
        <div className="flex items-center gap-1.5">
          <input
            type="text"
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            placeholder="新建标签名称"
            aria-label="新建标签名称"
            data-todo-tag-input="true"
            className="min-h-9 min-w-0 flex-1 rounded-md border border-line bg-surface px-2.5 text-sm text-ink outline-none focus:border-accent focus:ring-1 focus:ring-accent"
          />
          <button
            type="submit"
            disabled={busy || !draft.trim()}
            className="inline-flex min-h-9 shrink-0 items-center gap-1 rounded-md bg-accent px-2.5 text-xs font-medium text-surface transition-colors hover:bg-accent/90 disabled:opacity-45"
          >
            <Plus className="size-3.5" aria-hidden="true" />
            添加
          </button>
        </div>
        <div
          className="flex flex-wrap items-center gap-1"
          role="group"
          aria-label="标签颜色"
        >
          {COLOR_ORDER.map((color) => (
            <button
              key={color}
              type="button"
              aria-label={`颜色 ${color}`}
              aria-pressed={draftColor === color}
              onClick={() => setDraftColor(color)}
              data-todo-tag-color={color}
              className={`flex size-6 items-center justify-center rounded-full border ${
                draftColor === color ? "border-ink" : "border-transparent"
              }`}
            >
              <span
                className="size-3 rounded-full"
                style={{ backgroundColor: swatch(color) }}
                aria-hidden="true"
              />
            </button>
          ))}
        </div>
      </form>

      {error && (
        <p role="alert" className="text-xs text-danger">
          {error}
        </p>
      )}
    </section>
  );
}

