              </span>
              <span className="text-[11px] tabular-nums text-muted">
                {tag.taskCount}
              </span>
              <button
                type="button"
                disabled={busy}
                aria-label={`删除标签 ${tag.name}`}
                onClick={() => void handleDelete(tag)}
                data-todo-tag-delete={tag.name}
                className="inline-flex size-7 items-center justify-center rounded-md text-muted transition-colors hover:bg-danger/10 hover:text-danger disabled:opacity-45"
              >
                <Trash2 className="size-3.5" aria-hidden="true" />
              </button>
            </li>
          ))}
        </ul>
      )}

      <form onSubmit={(e) => void handleCreate(e)} className="flex items-center gap-1.5">
        <input
          type="text"
          value={name}
          onChange={(e) => setName(e.target.value)}
          placeholder="新建标签"
          aria-label="新建标签"
          data-todo-tag-catalog-input="true"
          className="min-h-8 min-w-0 flex-1 rounded-md border border-line bg-canvas px-2 text-xs text-ink outline-none focus:border-accent focus:ring-1 focus:ring-accent"
        />
        <button
          type="submit"
          aria-label="创建标签"
          disabled={busy || !name.trim()}
          className="inline-flex size-8 shrink-0 items-center justify-center rounded-md border border-line bg-surface text-accent transition-colors hover:bg-accent-soft disabled:opacity-45"
        >
          <Plus className="size-4" aria-hidden="true" />
        </button>
      </form>

      {error && (
        <p role="alert" className="text-[11px] text-danger">
          {error}
        </p>
      )}
    </section>
  );
}

export default function apply(ctx: Context): void {
  ctx.slot.register({
    name: "todo.item.badges",
    order: 10,
    component: TaskTagBadges,
  });
  ctx.slot.register({
    name: "todo.item.detail",
    order: 10,
    component: TaskTagEditor,
  });
  ctx.slot.register({
    name: "todo.sidebar.sections",
    order: 10,
    component: TagSidebarSection,
  });
}
